(function(){
  const particles = [];
  const N = 72;
  for(let i=0;i<N;i++){
    const zone = Math.random()<0.5?0:1;
    const y = zone===0 ? Math.random()*H()*0.28 : H()*0.72+Math.random()*H()*0.28;
    particles.push({
      x: Math.random()*W(),
      y: y,
      baseY: y,
      r: 2+Math.random()*4.5,
      speed: 0.15+Math.random()*0.35,
      phase: Math.random()*Math.PI*2,
      color: PALETTE[Math.floor(Math.random()*PALETTE.length)],
      drift: (Math.random()-0.5)*0.6
    });
  }
  let t=0;
  function draw(){
    ctx.clearRect(0,0,W(),H());
    t+=0.008;
    particles.forEach(p=>{
      p.phase+=p.speed*0.02;
      const alpha = 0.25+0.35*Math.sin(p.phase);
      const yy = p.baseY + Math.sin(t*1.2+p.phase)*10;
      const xx = p.x + Math.sin(t*0.6+p.phase)*p.drift*18;
      ctx.beginPath();
      ctx.arc(xx, yy, p.r, 0, Math.PI*2);
      ctx.fillStyle = p.color;
      ctx.globalAlpha = Math.max(0, alpha);
      ctx.shadowColor = p.color;
      ctx.shadowBlur = 10;
      ctx.fill();
      ctx.globalAlpha = 1;
      ctx.shadowBlur = 0;
    });
    requestAnimationFrame(draw);
  }
  draw();
})();
